-- 17ps.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-66f33620d5fb', 'doc', 'The 17Ps of funnel sections', null, 3306, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000000000, '57a7e000-0000-4000-8000-66f33620d5fb', 0, null, 'The 17Ps is the order of sections on a sales page or any page that asks for a decision. Use only the sections the page needs. An opt-in page might use six of them, and a long sales page can use all seventeen. Every section you leave out should be a decision.'),
  (5717000000001, '57a7e000-0000-4000-8000-66f33620d5fb', 1, null, 'The seventeen sections, in order
1. Promise: the outcome they want, in plain words, in the headline.
2. Problem: what makes them want a change now.
3. Pain Points: the symptoms they recognise from their own week.
4. Proof of Results: why you are a credible guide, with real results.
5. Personal Epiphany: how you found this way of doing it.
6. Process to Solution: the method that gets the result, in a few named steps.
7. Positioning of Offer: why this beats the other options they are weighing.
8. Price Anchor: the value shown next to the price, so the deal is easy to see.
9. Pricing Tables: only when there are several plans to choose from.
10. Product Breakdown: what is inside, item by item.
11. Product Bonuses: what else they get. Each bonus removes one reason not to buy.
12. Proof of Recommendations: reviews, testimonials and outside trust.
13. Perfect Persona: who it is for and who should skip it.
14. Project Spotlight: one or two case studies told in detail.
15. Pushback Reflex: the guarantee and the risk reversal.
16. Priority: why act now, with a real deadline or limit.
17. Promotional Bar: the announcement bar at the top and the final call to action at the bottom.

An FAQ can follow Priority when objections remain.'),
  (5717000000002, '57a7e000-0000-4000-8000-66f33620d5fb', 2, null, 'Default sections by page type
- Opt-in or lead page: Promotional Bar, Promise, Pain Points, Product Breakdown (what is in the freebie), Proof of Results and the call to action.
- Webinar or challenge registration: Promotional Bar, Promise, Pain Points, Product Breakdown (what they will learn), Proof of Results and Priority (the date).
- Low-ticket page ($7 to $47): Promotional Bar, Promise, Proof of Results, Personal Epiphany, Positioning (before and after), Product Breakdown, Product Bonuses, Price Anchor, Proof of Recommendations, Pushback Reflex, FAQ and Priority.
- Automated or mid-ticket sales page ($100 to $1,000): all seventeen, with Pricing Tables only when there are plans.
- High-ticket or application page: Promise, Problem, Pain Points, Proof of Results, Personal Epiphany, Process to Solution, Perfect Persona, Project Spotlight, Proof of Recommendations and Priority, with an application as the call to action. Usually no price on the page.
- Upsell or one-time offer page: Promise, Product Breakdown, Price Anchor, Pushback Reflex and Priority.'),
  (5717000000003, '57a7e000-0000-4000-8000-66f33620d5fb', 3, null, 'The 10P outline
The 10P outline is the compact version for pages that need every conversion section without a wall of text: Promise, Problem, Pain, Proof, Process, Positioning, Price, Product, Pushback and Priority. Keep all ten and make each one scannable with a short heading, two or three lines and a visual.'),
  (5717000000004, '57a7e000-0000-4000-8000-66f33620d5fb', 4, null, 'How long a page should be
As long as it takes to answer every question and objection the buyer has. Higher prices and colder traffic need more copy, because people need more belief before they buy. A warm audience buying a low-ticket product needs much less. Long copy works when it is easy to read: short headlines, bullets, proof blocks, visuals and a call to action between sections, so people can buy the moment they are ready.');

-- ai-business.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-4b2341fe9943', 'doc', 'AI agents and vibe coding', null, 2082, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000001000, '57a7e000-0000-4000-8000-4b2341fe9943', 0, null, 'AI is only as good as the context you give it. Write down your offers, audience, voice and frameworks once, and give them to every tool you use.'),
  (5717000001001, '57a7e000-0000-4000-8000-4b2341fe9943', 1, null, 'Your first agent
Pick a task you repeat every week that follows the same steps, like lead follow-up, research or turning a video into posts. Write the steps down first. Then give the agent five things: a role, the context it needs, the steps, the rules it must follow and the format of the output. Keep a human approval step before anything gets sent, published or paid.'),
  (5717000001002, '57a7e000-0000-4000-8000-4b2341fe9943', 2, null, 'A good agent prompt
- Role: who the agent is and who it works for.
- Context: the business, the offer, the audience and examples of good work.
- Steps: the method, in order.
- Rules: what it must never do, like inventing numbers or sending messages on its own.
- Output: the exact format you want back.'),
  (5717000001003, '57a7e000-0000-4000-8000-4b2341fe9943', 3, null, 'Scoping a vibe coding build
Write a one page brief before you build: who it is for, the one job it does, the inputs, the outputs, the screens, the data it stores and the services it connects to. Build the smallest version that does the one job, put it in front of real users, then add features.'),
  (5717000001004, '57a7e000-0000-4000-8000-4b2341fe9943', 4, null, 'Security basics for AI built apps
- API keys stay on the server and in environment variables. Never put them in browser code or in the repo.
- Turn on row level security for every database table.
- Check who is signed in on every request that reads or changes data.
- Rate limit anything that costs money per call.
- Read the code that handles payments and passwords yourself, or have someone review it.'),
  (5717000001005, '57a7e000-0000-4000-8000-4b2341fe9943', 5, null, 'Designing funnels with AI
Do the thinking first, then let AI build. Give it the client context, the brand bullets, the offer outline and the funnel strategy, then the copy, then the design direction: reference sites, fonts, palette and mood. Build and review one section at a time. Your job is taste and conversion judgment.'),
  (5717000001006, '57a7e000-0000-4000-8000-4b2341fe9943', 6, null, 'Selling AI builds
Sell the outcome the build creates, like more booked calls or hours saved each week. Show a working demo built for their business before the call, and price it as a project with an optional monthly plan for hosting and changes.');

-- ascension.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-738d6692ad04', 'doc', 'Ascension and the Profit Maximizer', null, 2363, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000002000, '57a7e000-0000-4000-8000-738d6692ad04', 0, null, 'The Profit Maximizer is an ascension model. Every customer gets a clear next step, so each one becomes worth more over time and you can afford to reach more people.'),
  (5717000002001, '57a7e000-0000-4000-8000-738d6692ad04', 1, null, 'The four levels
- Free: lead magnets and freebie funnels that bring people in and build trust.
- Low ticket, $7 to $47: a mass market offer that turns strangers into customers and pays for the ads.
- Mid ticket, $100 to $1,000: automated offers with more help and more access.
- Back end, $1,000 and up: high-ticket coaching, done for you work or a program, sold through an application or a call.

The front end gets the customer. The back end grows the business. Each level should solve the next problem the customer has once the last level worked, which makes the next step feel natural.'),
  (5717000002002, '57a7e000-0000-4000-8000-738d6692ad04', 2, null, 'The low-ticket funnel
Map the steps before you write copy: the front end offer, an order bump on the order form, upsell 1 (a quick result accelerator), upsell 2 (often recurring, like a membership or software), the confirmation page, and then the back end email sequence that invites buyers to the high-ticket offer.'),
  (5717000002003, '57a7e000-0000-4000-8000-738d6692ad04', 3, null, 'Bundle stacking
One core product that solves one problem, three to seven stack items that make the result faster or easier, and two or three bonuses that remove friction. Give every item a name, a one line description and a value.'),
  (5717000002004, '57a7e000-0000-4000-8000-738d6692ad04', 4, null, 'The break-even math
Blended order value equals the front end price, plus the bump take rate times the bump price, plus each upsell take rate times its price. When the cost to get a buyer is under the blended order value, the funnel pays for itself on day one.

Example with made up numbers: a $27 front end, a $17 bump taken by 30 percent of buyers and a $97 upsell taken by 10 percent gives 27 + 5.10 + 9.70, so $41.80 per buyer.'),
  (5717000002005, '57a7e000-0000-4000-8000-738d6692ad04', 5, null, 'Headline tests
For split tests, write up to 20 headline variants by rotating four parts: the opening hook, the credential, the deliverable and the benefit.'),
  (5717000002006, '57a7e000-0000-4000-8000-738d6692ad04', 6, null, 'The 7 step flywheel
Find, Convert, Upsell, Cross Sell, Ascend, Retain and Ignite. Find the right people. Convert them with a first offer. Upsell more of what they just bought. Cross sell something related that gets them the result faster. Ascend them to the higher offer. Retain them by keeping them getting results. Ignite referrals and content from happy customers. Most businesses only work on Find and Convert. The other five steps are where each customer becomes worth more.');

-- buyer-beliefs.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-22dd92a3eda9', 'doc', 'The 12 buyer beliefs', null, 1018, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000003000, '57a7e000-0000-4000-8000-22dd92a3eda9', 0, null, 'Before someone buys, they need to believe twelve things. A sales page, a VSL or a sales call should build each one.

1. They want the outcome and value it.
2. They admit they have the problem and want it solved soon.
3. They believe your solution can solve it.
4. They trust that you are the right person to help.
5. It makes sense to them why they have not solved it yet.
6. They see why your process is better than what they tried.
7. They see that people like them got results, which gives them hope.
8. They see that the value is worth more than the price.
9. They are willing to make time for it.
10. They see that doing nothing is the bigger risk.
11. They know exactly what happens next.
12. They feel a reason to solve it now.'),
  (5717000003001, '57a7e000-0000-4000-8000-22dd92a3eda9', 1, null, 'Using the list
Go through a page or a call script and mark where each belief gets built. A belief with no section behind it is usually where people drop off. Proof sections build beliefs 4 and 7, the price anchor builds 8, the guarantee builds 10 and the next steps section builds 11.');

-- clients.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-e4e6f4fd1c2d', 'doc', 'Getting your first clients', null, 1806, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000004000, '57a7e000-0000-4000-8000-e4e6f4fd1c2d', 0, null, 'Clients come from proof and conversations. Build the proof first, then start the conversations.'),
  (5717000004001, '57a7e000-0000-4000-8000-e4e6f4fd1c2d', 1, null, 'Position, Promotion, Partner
- Position: pick one growing market with buying power, one clear offer and a small portfolio.
- Promotion: create magnets like a free audit, a template or a small tool, send gift first outreach, and post content that compounds.
- Partner: close by auditing their business, acting like a consultant and prescribing what they need. Then retain them and grow into bigger work.'),
  (5717000004002, '57a7e000-0000-4000-8000-e4e6f4fd1c2d', 2, null, 'Start with people who know you
Make a list of thirty people who already know you, send each a personal message and offer to build something for them first. The first clients usually come from your own network.'),
  (5717000004003, '57a7e000-0000-4000-8000-e4e6f4fd1c2d', 3, null, 'A portfolio with no clients
Build concept projects. Pick real brands or creators in your market, design what their funnel or page could look like and show it. Add your own live projects. A portfolio page needs a one line promise, the concept work, client work when you have it, your process and one clear call to action. A strong concept piece often lands the first client.'),
  (5717000004004, '57a7e000-0000-4000-8000-e4e6f4fd1c2d', 4, null, 'Gift first outreach
Send something made for them before you ask for anything: a redesigned hero section, a short audit video, three headline rewrites. Show what you did. Keep the message short, skip the long intro and ask for an easy yes.'),
  (5717000004005, '57a7e000-0000-4000-8000-e4e6f4fd1c2d', 5, null, 'Picking a niche
Pick a market where people already spend money and where you can reach the buyers. Wealth, health and relationships are the classic three. Choose an industry you care about, because you will be in it for years.'),
  (5717000004006, '57a7e000-0000-4000-8000-e4e6f4fd1c2d', 6, null, 'Communities and referrals
Go where your clients already gather: online communities, groups and the comment sections of people in your niche. Help first. For referrals, ask right after a client gets a result, and make it easy with a short message they can forward.');

-- content.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-e5c855cc892e', 'doc', 'Content, personal brand and YouTube', null, 2498, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000005000, '57a7e000-0000-4000-8000-e5c855cc892e', 0, null, 'Content does two jobs: it brings the right people in, and it builds the trust that makes them buy later. Ground every idea in a real signal and point it at something you offer.'),
  (5717000005001, '57a7e000-0000-4000-8000-e5c855cc892e', 1, null, 'The CONTENT mix
Seven types of content that grow a business:
- Customer results: proof through success stories and projects.
- Offer differentiation: what makes your way different.
- New discoveries: lessons you are learning right now.
- Thought leadership: truths you believe in, even unpopular ones.
- Education and entertainment: helpful tips that sound like a person.
- Narrative framing: stories, metaphors and analogies.
- Trends and news: be the source for what is happening in your industry.

Mix all seven and your feed builds proof, authority and connection at the same time.'),
  (5717000005002, '57a7e000-0000-4000-8000-e5c855cc892e', 2, null, 'An idea worth making
Every idea gets a working title, a hook for the first line or the first five seconds, the angle, why it should work (a post or video in your niche that did far better than usual), and which offer or freebie it points to. Study outliers and repeat the pattern with your own angle.'),
  (5717000005003, '57a7e000-0000-4000-8000-e5c855cc892e', 3, null, 'YouTube
- Titles: under 60 characters, specific, with a curiosity gap the video pays off. Write ten options and pick the one you would click.
- Thumbnails: one focal point and three to five words that add to the title.
- Scripts: a hook in the first 5 to 10 seconds that confirms the title, a short setup, chapters with an early quick win, and one call to action.
- Numbers: a click-through rate under 4 percent usually means a packaging problem with the title and thumbnail. An average view duration over 50 percent is good.
- Consistency: a steady schedule you can keep beats bursts, because every upload teaches you something.'),
  (5717000005004, '57a7e000-0000-4000-8000-e5c855cc892e', 4, null, 'The 12 principles of personal branding
Personality, Authority, Positioning, Credibility, Pricing, Relevance, Engagement, Framework, Portfolio, Association, Endorsement and Celebrity. The first group is how people see you: likable, expert, essential and credible. The middle group is how you show up: pricing like a specialist, speaking their language and building real engagement. The last group is leverage: a named framework, a portfolio of proof, who you are associated with, who endorses you, and in time being known in your space.'),
  (5717000005005, '57a7e000-0000-4000-8000-e5c855cc892e', 5, null, 'Posts and announcements
Lead with the most interesting line, keep one idea per post and end with one clear next step. To announce a new offer, say what it is, who it is for, the outcome, the proof and how to get it, and show it in action with a screenshot or a short video.');

-- conversion-levers.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-0d4fa18e8dbb', 'doc', 'Conversion levers for any page', null, 1916, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000006000, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 0, null, 'These are the levers you can pull on a page without spending more on ads or content. Go through them line by line and fix what is missing before you touch the design.'),
  (5717000006001, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 1, null, 'The headline
The headline has one job: make them read the next line. Make it benefit driven (why they should care), outcome focused (the result they get), specific and a little curious. "Feel unstoppable confidence in 7 days or less" gives the reader a result and a timeframe. "Fix your mindset" gives them neither.'),
  (5717000006002, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 2, null, 'The subheadline
Add a simple mechanism, a timeframe and the guarantee if you have one.'),
  (5717000006003, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 3, null, 'Buttons that sell the click
Generic buttons like Submit, Click Here and Get Started say nothing about what happens next. Turn the action into a benefit: Get Instant Access, Download Your Free Guide, Book Your Free Strategy Call. Words like free and instant make it stronger. A game plan session sounds like it is about their strategy, and an application sounds exclusive.'),
  (5717000006004, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 4, null, 'Numbers and data
Specific numbers build belief. "Helped 212 clinics" lands harder than "helped hundreds of businesses". Only use numbers you can back up.'),
  (5717000006005, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 5, null, 'Proof next to the claims
Place a testimonial, a screenshot or a result right after each big claim, where the doubt shows up.'),
  (5717000006006, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 6, null, 'Risk reversal
State the guarantee in plain words under every buy button.'),
  (5717000006007, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 7, null, 'A real reason to act now
A real deadline, a bonus that expires or a limited number of spots. Fake timers break trust.'),
  (5717000006008, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 8, null, 'Clarity
One page, one action. Remove links and choices that pull attention away from that action. Check the page on a phone, because most visitors will see it there first.'),
  (5717000006009, '57a7e000-0000-4000-8000-0d4fa18e8dbb', 9, null, 'Conversion design
Conversion design means every element moves the right person one step closer to a decision: a clear hierarchy, a headline that earns the next scroll, proof where doubt shows up, buttons that sell the click and nothing that distracts from the action. The principles repeat across every niche, so it is a skill you can learn.');

-- conversions.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-70dabe1cebdf', 'doc', 'The CONVERSIONS checklist', null, 1324, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000007000, '57a7e000-0000-4000-8000-70dabe1cebdf', 0, null, 'CONVERSIONS is an eleven point check for any page that sells. Read the page once for each letter and mark what is missing.

1. Clear outcome: the headline says the result in plain words, for a specific person.
2. Opportunity selling: the page sells the future the buyer gets, with the features as support.
3. New method: the page explains why this way of getting the result is different from what they tried.
4. Value proposition: one sentence says what they get, how fast and why it is worth it.
5. Empathy: the page shows you understand their situation in their own words.
6. Results: real outcomes with numbers, names and timeframes, where you have them.
7. Social proof: testimonials, reviews, logos, case studies and community size.
8. Irresistible offer: a stack, bonuses and a price anchor that make yes the easy choice.
9. Objection handling: the top doubts get answered where they show up, plus an FAQ.
10. Next steps: one clear action, repeated, with what happens after the click.
11. Scarcity: a real deadline or limit. Only use scarcity that is true.'),
  (5717000007001, '57a7e000-0000-4000-8000-70dabe1cebdf', 1, null, 'How to use it
Score each letter as present, weak or missing. Fix the missing ones first, starting from the top of the page, because most visitors never reach the bottom. Then pair it with the 17P outline for the page type, which tells you where each fix belongs.');

-- copywriting.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-b9b153d81214', 'doc', 'Copy: awareness stages and structures', null, 2704, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000008000, '57a7e000-0000-4000-8000-b9b153d81214', 0, null, 'Good copy starts with the reader. Name the goal of the piece, who reads it and how aware they are, then pick the structure.'),
  (5717000008001, '57a7e000-0000-4000-8000-b9b153d81214', 1, null, 'The five awareness stages
- Unaware: they do not know they have the problem. Lead with a story or a pattern interrupt.
- Problem aware: they feel the pain. Name it in their words.
- Solution aware: they know solutions exist. Show why this method is different.
- Product aware: they know your offer. Give proof and answer objections.
- Most aware: they are ready. Make a direct offer and remove friction.'),
  (5717000008002, '57a7e000-0000-4000-8000-b9b153d81214', 2, null, 'Pick a structure
- PAS, problem, agitate, solution: ads and emails.
- AIDA, attention, interest, desire, action: cold pages.
- Before, after, bridge: transformations.
- PASTOR, problem, amplify, story, transformation, offer, response: long sales copy.
- Story: warm audiences.
- Direct offer: retargeting and people who already know the product.

Pages follow the 17P outline for their type.'),
  (5717000008003, '57a7e000-0000-4000-8000-b9b153d81214', 3, null, 'Hooks
The first line calls out the problem, the promise or the opportunity. Write three hooks with different angles, then pick the one you would stop for.'),
  (5717000008004, '57a7e000-0000-4000-8000-b9b153d81214', 4, null, 'The Winning Ad Formula
A structure for long form ads: a hook that stops the scroll, why they should listen to you, a high perceived value and then the lower price, the easy button, proof, a tease of what they do not know yet, how simple it is, a metaphor they can picture, the steps, the name of the system, the effort that went into it, the bonuses, exactly what to do, real urgency, what happens after they buy, and the risk reversal.'),
  (5717000008005, '57a7e000-0000-4000-8000-b9b153d81214', 5, null, 'A VSL script in five parts
1. A polarizing hook that challenges what they believe.
2. The old method they use now and why it keeps failing.
3. The new method, your different way to the result.
4. The proven system: the steps and the proof that it works.
5. The unique opportunity: the offer and why now.

Keep it conversational, as if you talk to one person. Read it out loud and cut everything that sounds like a commercial.'),
  (5717000008006, '57a7e000-0000-4000-8000-b9b153d81214', 6, null, 'Stories that sell
Open in the moment, show the struggle, show the turning point, show the result, then connect it to the reader''s situation. A story lets people feel the before and after for themselves.'),
  (5717000008007, '57a7e000-0000-4000-8000-b9b153d81214', 7, null, 'Objections to answer
Too expensive, no time, they do not trust you yet, it looks complicated, it will not work for them, maybe later, and who are you. Answer the ones that apply right where the doubt shows up on the page.'),
  (5717000008008, '57a7e000-0000-4000-8000-b9b153d81214', 8, null, 'Copy that sounds human
Conversational and first person, short paragraphs, specific numbers, no hype, no exclamation points and no filler. Use exact offer names, prices, guarantees and dates, and never invent results. When you write with AI, give it samples of your own writing, your offer details and the structure, then edit the draft line by line.');

-- cro-audit.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-17d1a83c1b1d', 'doc', 'Conversion audit order', null, 1482, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000009000, '57a7e000-0000-4000-8000-17d1a83c1b1d', 0, null, 'Fix a funnel in order of impact. Most of the lift comes from the first three steps, and no amount of button testing fixes a weak offer.

1. The offer.
2. Message to market match: the ad or post and the page make the same promise to the same person.
3. Page structure: the 17P outline for that page type.
4. Trust and proof.
5. Friction: long forms, unclear steps, surprise costs.
6. Technical: load speed, the mobile layout, broken links.
7. Small details: button colors, icons and microcopy.'),
  (5717000009001, '57a7e000-0000-4000-8000-17d1a83c1b1d', 1, null, 'Find the weakest step first
Read the real numbers for each step: opt-in rate, sales page conversion, order form completion, upsell take rate and refunds. Rough ranges to compare against: opt-in pages 20 to 45 percent, sales pages on cold traffic 1 to 4 percent, order forms 50 to 75 percent, upsells 10 to 25 percent. These are rough guides. Your own past numbers are the better benchmark.'),
  (5717000009002, '57a7e000-0000-4000-8000-17d1a83c1b1d', 2, null, 'Audit the page
Go through the CONVERSIONS checklist, the 17P outline for the page type and the Evidence Quadrant. Name the top three issues and fix those first.'),
  (5717000009003, '57a7e000-0000-4000-8000-17d1a83c1b1d', 3, null, 'Write the test
Write every test as one sentence before you build it: because [observation], we believe [change] will [outcome] for [audience]. We will know when [metric] moves by [amount].

Rank tests by impact, confidence and ease. Test one change at a time, run each test for full weeks and wait for 95 percent confidence before you call a winner. Keep a log of every test and what it taught you, so the next page starts from your winners.');

-- digital-products.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-15374e45ace8', 'doc', 'Digital products', null, 1966, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000010000, '57a7e000-0000-4000-8000-15374e45ace8', 0, null, 'A digital product packages a transformation so it can be sold and delivered without your time for every buyer.'),
  (5717000010001, '57a7e000-0000-4000-8000-15374e45ace8', 1, null, 'Input, method, output
The simplest structure is their input, your method and their output. A meal planner, a workout builder, a pricing calculator or a content planner all follow it. AI helps at every step: research the market, draft the method, build the tool, write the sales page and create the content.'),
  (5717000010002, '57a7e000-0000-4000-8000-15374e45ace8', 2, null, 'Your first product
Pick one transformation in a market where people already spend money. Make something they use every week, like a tool, a template, a planner or a calculator. Validate before you build too much: talk to buyers, presell or run a small test. Keep the first product simple, specific and quick to deliver.'),
  (5717000010003, '57a7e000-0000-4000-8000-15374e45ace8', 3, null, 'Pick the format by the need
- They need to learn a skill once: a short course.
- They need to do a task again and again: a template or a tool.
- They need support over time: a membership or a community.
- They need accountability and feedback: coaching or a cohort.'),
  (5717000010004, '57a7e000-0000-4000-8000-15374e45ace8', 4, null, 'Pricing a digital product
Price from the result and from where it sits on the ascension ladder. Low ticket at $7 to $47 works as a front end that pays for ads. A product that saves real time or money every week can carry a monthly price.'),
  (5717000010005, '57a7e000-0000-4000-8000-15374e45ace8', 5, null, 'Selling without a big audience
A low-ticket funnel with small paid tests, partners who already have the audience, and helpful posts in communities where your buyers gather. Each sale also shows you which message works.'),
  (5717000010006, '57a7e000-0000-4000-8000-15374e45ace8', 6, null, 'Micro tools
A micro tool is a small app that solves one problem: a calculator, a generator, a planner or an audit. It works as a lead magnet, a product or a bonus, and people value it because they get a result in seconds. With an AI builder you can make one in an afternoon.'),
  (5717000010007, '57a7e000-0000-4000-8000-15374e45ace8', 7, null, 'Why most courses fail
They teach everything they know when the buyer wanted one result. Cut every lesson that does not move the buyer toward that result, add a quick win in the first day, and add tools and templates so they can apply it.');

-- dm-sales.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-3ae0ef5262f1', 'doc', 'DM sales: Connect, Collect, Close', null, 1739, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000011000, '57a7e000-0000-4000-8000-3ae0ef5262f1', 0, null, 'The 3x3x3 system closes sales in direct messages: three stages with three moves each. Every message earns the next reply.'),
  (5717000011001, '57a7e000-0000-4000-8000-3ae0ef5262f1', 1, null, 'Connect
1. Open with something specific to them, like a post they wrote or a result they shared.
2. Build rapport with a real question about their world.
3. Show quiet authority with one short line about the work you do, with no pitch.'),
  (5717000011002, '57a7e000-0000-4000-8000-3ae0ef5262f1', 2, null, 'Collect
1. Ask where they are now.
2. Ask what is in the way.
3. Ask where they want to be. One question per message.'),
  (5717000011003, '57a7e000-0000-4000-8000-3ae0ef5262f1', 3, null, 'Close
1. Bridge with their own words: you said this is the problem and this is where you want to be.
2. Present the transformation and what is included before the price.
3. Handle the top objection and ask softly, like: want me to send the details?'),
  (5717000011004, '57a7e000-0000-4000-8000-3ae0ef5262f1', 4, null, 'The 3 Cs of closing
Connect, Collect and Close also work on calls. Audit their situation first, then prescribe the solution like a doctor. Sell the vision of the result, then agree on scope, price and start date. If it is not a fit, say so. That honesty is a big reason people say yes when it is a fit.'),
  (5717000011005, '57a7e000-0000-4000-8000-3ae0ef5262f1', 5, null, 'Proof, price and availability
When people hire, they want three things fast: examples of the work, the price and when you can start. Give them those three early and keep messages short.'),
  (5717000011006, '57a7e000-0000-4000-8000-3ae0ef5262f1', 6, null, 'Platforms
- Instagram: short and casual, with voice notes once the conversation is warm.
- LinkedIn: no pitch in the first message.
- WhatsApp: personal, one idea per message.
- Facebook: keyword triggers on posts can start conversations for you.'),
  (5717000011007, '57a7e000-0000-4000-8000-3ae0ef5262f1', 7, null, 'Objections
Validate the concern, clarify what is really behind it, reframe it and ask again. Too expensive often means the value is still unclear, so go back to what the result is worth to them.'),
  (5717000011008, '57a7e000-0000-4000-8000-3ae0ef5262f1', 8, null, 'Follow-up
Follow up on day 1, 3, 7 and 14, each time with an easy way out. Never use guilt.');

-- email.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-8494d14d20f7', 'doc', 'Email that sells', null, 885, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000012000, '57a7e000-0000-4000-8000-8494d14d20f7', 0, null, 'Every email has a subject line, a preview text and a body. One story, one idea and one call to action per email.'),
  (5717000012001, '57a7e000-0000-4000-8000-8494d14d20f7', 1, null, 'Sequences
- Welcome, after an opt-in: deliver the freebie, tell your story, share a quick win, then invite them to the next step.
- Launch: follow the launch phases, with every email written in full and dated.
- Buyers: onboarding on day 0, 1, 3 and 7, so they start and get a first result.
- Non-buyers after a launch: empathy, a downsell and a free resource.
- Abandoned checkout: a reminder within the hour, then an answer to the top objection the next day.'),
  (5717000012002, '57a7e000-0000-4000-8000-8494d14d20f7', 2, null, 'Subject lines
Short, specific and curious. Write five, pick one, and keep the promise of the subject line in the first two lines of the email.'),
  (5717000012003, '57a7e000-0000-4000-8000-8494d14d20f7', 3, null, 'Writing the body
Write like you talk to one person. Short paragraphs, one link, a P.S. that repeats the call to action. Match the length and tone of your best past emails.');

-- evidence-quadrant.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-4d8c72e28740', 'doc', 'The Evidence Quadrant', null, 1246, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000013000, '57a7e000-0000-4000-8000-4d8c72e28740', 0, null, 'The Evidence Quadrant sorts proof into four types. A page that covers all four feels safe to buy from. Use real proof only.'),
  (5717000013001, '57a7e000-0000-4000-8000-4d8c72e28740', 1, null, 'The four types
- Internal direct: your own results, experience and before and after stories.
- Internal indirect: data, research and a story that shows why you see the problem clearly.
- External direct: testimonials, reviews and case studies from customers.
- External indirect: signals from the outside world, like engagement, shares, press, partners and growth.'),
  (5717000013002, '57a7e000-0000-4000-8000-4d8c72e28740', 2, null, 'Where proof goes
Put proof right after the claim it supports. A results section after the promise, a testimonial next to the price, a case study before the guarantee. When you are new and have no customer results yet, use concept work, your own projects, a free pilot with a few people, or data from a trusted source, and say plainly what it is.'),
  (5717000013003, '57a7e000-0000-4000-8000-4d8c72e28740', 3, null, 'Urgency without pressure
Give a real reason to act now: a launch close date, a bonus that ends, limited spots for something you deliver by hand, or a price that goes up on a set date. Say why the limit exists.'),
  (5717000013004, '57a7e000-0000-4000-8000-4d8c72e28740', 4, null, 'Risk reversal
A risk reversal moves the risk from the buyer to you. Write it as a short promise: what you guarantee, for how long and what they do to claim it. Put it under every buy button and in the FAQ.');

-- funnel-formula.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-4c5917a6aa2e', 'doc', 'The Funnel Formula', null, 3637, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000014000, '57a7e000-0000-4000-8000-4c5917a6aa2e', 0, null, 'The Funnel Formula is nine layers, built in order. Each layer feeds the next, so a layer only starts when the one above it is locked. The first three are inputs, the fourth is the strategy decision, and the last five are the build.'),
  (5717000014001, '57a7e000-0000-4000-8000-4c5917a6aa2e', 1, null, 'The nine layers
1. Client Context: who the business serves, what it sells, where it is today and the goal.
2. Brand Bullets: the voice, the story, the proof and the visual style, written as short bullets.
3. Offer Outline: the transformation, the timeline, what is inside, the price, the bonuses and the guarantee.
4. Strategy: which funnel, for which traffic, with which launch format.
5. Copy: every page written section by section with the 17Ps.
6. Design: the pages laid out around the copy.
7. Automations: the emails, texts, tags, pipeline stages and reminders that run after each step.
8. Traffic: where visitors come from, organic or paid, cold or warm.
9. CRO: measure each step, find the weakest one, fix it and test.

Copy comes before design because the words decide what each section has to show. Strategy comes before copy because the funnel type decides which pages exist at all.'),
  (5717000014002, '57a7e000-0000-4000-8000-4c5917a6aa2e', 2, null, 'The strategy decision
Three inputs decide the strategy.
- Traffic temperature. Cold traffic has never heard of you and needs a lead funnel or a low-ticket offer first. Warm traffic knows you and can go straight to a sales page. Hot traffic is ready to buy and can land on the checkout.
- Price point. The higher the price, the more trust the funnel has to build before the ask.
- Launch format. Live means a set date, a deadline and a cart that opens and closes. Evergreen means always on, with a nurture sequence doing the work.'),
  (5717000014003, '57a7e000-0000-4000-8000-4c5917a6aa2e', 3, null, 'Funnel type by price point
- Free: a lead funnel. Opt-in page, thank you page and a welcome email sequence.
- $1 to $100: a low-ticket funnel that pays for its own ads. Sales page, order form with an order bump, one or two upsells and a confirmation page.
- $100 to $1,000: an automated sales funnel. Sales page or VSL, order form and onboarding emails.
- $1,000 to $10,000: a webinar or VSL funnel. Registration, the presentation, the offer and a replay sequence.
- $10,000 and up: an application or book a call funnel. The page qualifies people and a conversation closes them.'),
  (5717000014004, '57a7e000-0000-4000-8000-4c5917a6aa2e', 4, null, 'Live launch or evergreen
Start live when the offer is new. A live launch puts real people in front of the offer within days, so you hear the objections and the questions fast. Once the offer sells live and the message is clear, turn the best version into an evergreen funnel.'),
  (5717000014005, '57a7e000-0000-4000-8000-4c5917a6aa2e', 5, null, 'Webinar or VSL
A live webinar shows you the objections in real time through the questions people ask. A VSL is the recorded and tightened version that runs every day. Many offers start as a webinar and become a VSL once the pitch converts.'),
  (5717000014006, '57a7e000-0000-4000-8000-4c5917a6aa2e', 6, null, 'The funnel ecosystem
One funnel rarely carries a whole business. An ecosystem connects a lead funnel, a front end offer, upsells, a core offer and a high-ticket back end, with email and content moving people from one step to the next. Every piece has one job and one number that shows it works.'),
  (5717000014007, '57a7e000-0000-4000-8000-4c5917a6aa2e', 7, null, 'Automations every funnel needs
- A confirmation email the moment someone opts in or buys.
- A nurture or onboarding sequence for the first week.
- Tags or pipeline stages, so you can see where each person is.
- A follow-up for people who start checkout and leave.
- Reminders for any live event or call.'),
  (5717000014008, '57a7e000-0000-4000-8000-4c5917a6aa2e', 8, null, 'Is the offer ready for a funnel
An offer is ready when you can say who it is for and what result they get in one sentence, a few people have bought it or asked for it, and you have some proof. A funnel scales what already sells in conversations. If nobody has bought yet, sell it by hand first.');

-- launches.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-5ac122eb65df', 'doc', 'Launch phases', null, 1615, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000015000, '57a7e000-0000-4000-8000-5ac122eb65df', 0, null, 'A launch is a set window where an offer opens, gets attention and closes. Plan it backwards from the close date.'),
  (5717000015001, '57a7e000-0000-4000-8000-5ac122eb65df', 1, null, 'Pick the launch type
- Under 500 people in your audience: a seed launch. Sell by hand to a small group and prove the offer.
- 500 to 5,000: an internal or webinar launch to your own audience.
- 5,000 and up, with a proven product: a partner launch with affiliates.
- A community goal: a challenge over three to five days.
- Hands off: an evergreen funnel with a nurture sequence.'),
  (5717000015002, '57a7e000-0000-4000-8000-5ac122eb65df', 2, null, 'The four phases
1. Pre-prelaunch: hints, behind the scenes posts and a waitlist.
2. Prelaunch: three free pieces of content. The opportunity, the transformation and the experience of what it is like inside.
3. Open cart: doors open, the value stack, proof, objections, a bonus that expires, the final 24 hours and three emails on the last day.
4. Post-launch: onboard the buyers, survey the people who did not buy and offer them a downsell or a free resource.'),
  (5717000015003, '57a7e000-0000-4000-8000-5ac122eb65df', 3, null, 'The launch math
Sales needed equals the goal divided by the price. Visitors needed equals the sales needed divided by the conversion rate. Example with made up numbers: a $10,000 goal at a $500 price needs 20 sales. At a 2 percent conversion rate, that is 1,000 visitors to the sales page.'),
  (5717000015004, '57a7e000-0000-4000-8000-5ac122eb65df', 4, null, 'Launch emails
Write every email in full with its send day, its subject line and one call to action. Use real scarcity only: a real close date, a bonus that really ends, or a real cap on spots.'),
  (5717000015005, '57a7e000-0000-4000-8000-5ac122eb65df', 5, null, 'Webinar launches
Hook, your story, three teaching points that each break one false belief, then the offer and live questions. After the webinar, send three replay emails over 48 hours.');

-- offers.md
insert into public.gai_lib_sources (id, kind, title, url, chars, published_at) values ('57a7e000-0000-4000-8000-b265c10d1671', 'doc', 'The 3T Offer Triangle', null, 2441, null);
insert into public.gai_lib_chunks (id, source_id, idx, at_s, body) values
  (5717000016000, '57a7e000-0000-4000-8000-b265c10d1671', 0, null, 'The 3T Offer Triangle tests an offer on three sides before you build a funnel for it. A funnel only sells an offer that is already clear.'),
  (5717000016001, '57a7e000-0000-4000-8000-b265c10d1671', 1, null, 'The three sides
- Transformation: who goes from what painful before to what after. Say it in one sentence: I help [who] go from [before] to [after].
- Timeline: how fast they get there, with milestones along the way. A clear timeline makes the result feel reachable.
- Trust: the proof that it works and the guarantee that makes it safe to try.

Score each side out of 10. Fix anything under 7 before you write the page.'),
  (5717000016002, '57a7e000-0000-4000-8000-b265c10d1671', 2, null, 'The Golden Offer Quadrant
Score the offer against the alternatives with four questions. New: is it a new way to get the result? Better: does it get a better result? Faster: does it get there in less time? Convenient: does it take less effort and fewer steps, or is it done for them? An offer that wins on one has a reason to exist. One that wins on several is easy to sell. If it wins on none, fix the offer before you write the funnel.'),
  (5717000016003, '57a7e000-0000-4000-8000-b265c10d1671', 3, null, 'The value stack
Write the offer as numbered text. The core product comes first, then each stack item with a plain name, a one line outcome and its value. Each bonus removes one specific reason not to buy: a done for you template for no time, a group call for low confidence, a setup video for no tech skills.'),
  (5717000016004, '57a7e000-0000-4000-8000-b265c10d1671', 4, null, 'The price anchor
Show the value before the price, so the number lands against the value. A five layer anchor, using only true numbers: what people normally pay for this result, the total value of the stack, the value of the items sold separately, the regular price and today''s price.'),
  (5717000016005, '57a7e000-0000-4000-8000-b265c10d1671', 5, null, 'Guarantees
A guarantee moves the risk from the buyer to you. Pick one you can keep: money back within a set number of days, a results guarantee with clear conditions, or a promise to keep helping until they get the result when they do the work. Write it in plain words under every buy button.'),
  (5717000016006, '57a7e000-0000-4000-8000-b265c10d1671', 6, null, 'Pricing
Price from the outcome. Ask what the result is worth to the buyer over the next twelve months, then price at a fraction of that so the decision is easy. Then check the price against the funnel: the right price is one your funnel can sell profitably.'),
  (5717000016007, '57a7e000-0000-4000-8000-b265c10d1671', 7, null, 'Productized services
A productized service is a service with a fixed scope, a fixed price and a fixed timeline, like a funnel build in 14 days or a monthly content package. It is easier to sell because the buyer knows exactly what they get, and easier to deliver because every project follows the same steps.');

-- library/playbook.json
insert into public.gai_lib_playbook (id, topic, question, keywords, answer, sources, position) values
  ('57a7e001-0000-4000-8000-dd6d4f90e4a4', 'Funnel strategy', 'How do you come up with a funnel strategy?', 'funnel strategy plan which funnel type choose decide', 'I never pick a funnel because I like the look of it. Three inputs decide the strategy: how warm the traffic is, the price point, and the launch format. Cold traffic needs a lead funnel first. Warm traffic can go straight to a sales page. Hot traffic can land on the checkout. Low ticket points to an automated sales funnel, mid ticket to a webinar or VSL, high ticket to book a call or an application. Then decide live or evergreen. Live means a deadline and a cart open and close sequence. Evergreen means always on with ongoing nurture. Lock that decision before you write a single word, because strategy is layer four of the Funnel Formula and everything after it reads from it.', array['The Funnel Formula']::text[], 1),
  ('57a7e001-0000-4000-8000-77aa8105f7a7', 'Funnel strategy', 'What is the Funnel Formula?', 'funnel formula nine layers framework process order', 'The Funnel Formula is nine layers, built in order, and each layer feeds the next. Nothing gets built until the layer above it is locked. The first three are inputs: Client Context, Brand Bullets and the Offer Outline. Layer four is the Strategy decision. Then come the build layers: Copy, Design, Automations, Traffic and CRO. The order matters. Copy comes before design on purpose, because copy decides the layout, not the other way around. Most people jump straight into a template and wonder why it does not convert. When you follow the layers, the page almost writes itself because you already know who it is for, what they are buying and what kind of funnel it needs to be.', array['The Funnel Formula']::text[], 2),
  ('57a7e001-0000-4000-8000-e94f2f2426e2', 'Funnel strategy', 'What funnel should I use for a high ticket offer?', 'high ticket funnel application book a call coaching', 'For high ticket, the goal of the funnel is a conversation, not a checkout. That usually means a book a call or application funnel. If the traffic is cold, put a nurture bridge in front of it: a lead magnet, a short training or a VSL that builds the beliefs they need before they ever apply. Cold plus high ticket plus evergreen is an application funnel with a nurture bridge. The application itself does work for you. It signals that the offer is exclusive and it qualifies people so you only talk to buyers. Keep the page focused on the transformation and proof, and let the call or DM do the closing.', array['The Funnel Formula']::text[], 3),
  ('57a7e001-0000-4000-8000-bb7faab6c856', 'Funnel strategy', 'What funnel should I use for a low ticket offer?', 'low ticket funnel tripwire self liquidating order bump upsell', 'Low ticket wants an automated sales funnel. A short sales page or a direct checkout page, an order bump, and one or two upsells. The front end offer is not where the profit comes from. Its job is to turn a stranger into a customer and cover the cost of getting them there. The money is made on the back end, through the bump, the upsells and the ascension into your bigger offers. That is the Profit Maximizer idea: every customer who buys something small gets a clear next step. If traffic is warm, send them straight to the page. If it is cold, the ad itself has to do the warming.', array['The Funnel Formula', 'Ascension and the Profit Maximizer']::text[], 4),
  ('57a7e001-0000-4000-8000-e0d7093cfbdd', 'Funnel strategy', 'What is the difference between a live launch and an evergreen funnel?', 'live launch evergreen always on cart open close', 'A live launch has a real deadline. You open the cart, run a launch sequence, and close it. The urgency is real, so conversion is usually higher, but it takes energy every time you run it. Evergreen is always on. People come in through ads or content, go through a nurture sequence, and buy on their own timeline, often with a personal timer or a bonus that expires. My advice: validate the offer with a live launch first, because you learn the objections fast. Once you know what converts, turn the winning version into evergreen so it sells for you while you work on the next asset.', array['Launch phases', 'The Funnel Formula']::text[], 5),
  ('57a7e001-0000-4000-8000-8b2c50a47388', 'Funnel strategy', 'How does traffic temperature change my funnel?', 'traffic temperature cold warm hot audience', 'Traffic temperature is how much someone knows and trusts you when they land. Cold traffic has never heard of you, so asking for a sale right away is like proposing on a first date. Give them a lead magnet, a training or a quiz first. Warm traffic knows you from content or email, so a sales page or VSL works. Hot traffic already wants to buy, so send them straight to the checkout and remove friction. The mistake I see most is people sending cold ad traffic to a high ticket sales page and blaming the page. Match the step to the temperature.', array['The Funnel Formula']::text[], 6),
  ('57a7e001-0000-4000-8000-cd3dc874c61b', 'Funnel strategy', 'What is a funnel ecosystem?', 'funnel ecosystem value ladder ascension multiple funnels', 'One funnel is a tactic. An ecosystem is a business. It is a set of funnels that hand people to each other: content and lead magnets bring people in, a low ticket offer turns them into customers, and mid and high ticket offers ascend them. I think of it as the 7 Step Profit Maximization Flywheel: Find, Convert, Upsell, Cross Sell, Ascend, Retain and Ignite. Each step has its own funnel or automation. The point is that you stop needing new leads for every sale, because the people already in your world keep moving to the next step that helps them.', array['Ascension and the Profit Maximizer']::text[], 7),
  ('57a7e001-0000-4000-8000-b53ac3c9a207', 'Funnel strategy', 'What is the Profit Maximization Flywheel?', 'flywheel find convert upsell cross sell ascend retain ignite', 'It is seven steps that turn one customer into a long relationship. Find: attract the right people. Convert: get them to say yes to a first offer. Upsell: offer more of what they just bought. Cross Sell: offer something related that helps them get the result faster. Ascend: move them to your higher level offer. Retain: keep them getting results so they stay. Ignite: turn happy customers into referrals and content. Most businesses only work on Find and Convert and keep paying for new leads. The flywheel makes each customer worth more, which means you can afford to acquire them.', array['Ascension and the Profit Maximizer']::text[], 8),
  ('57a7e001-0000-4000-8000-3f71716154df', 'Funnel strategy', 'How do I know if my offer is ready for a funnel?', 'offer ready validate before funnel golden offer quadrant', 'Score it on the Golden Offer Quadrant: is it New, Better, Faster or Convenient compared to what they already have? If it is none of those, a funnel will just help you fail faster. Then check the Offer Outline: a clear before and after state, a one sentence promise, the surface problem, the real cost of staying stuck, your signature process, the price and why, and bonuses that kill objections. If you can write all of that on one page, you are ready. If you cannot, the problem is the offer, not the funnel, and no design will fix it.', array['The Funnel Formula']::text[], 9),
  ('57a7e001-0000-4000-8000-9df9ea0751a7', 'Funnel strategy', 'Should I build a webinar or a VSL funnel?', 'webinar vsl video sales letter mid ticket', 'Both work best for mid ticket offers where people need more belief before they buy. A webinar gives you a live moment, real urgency and the chance to answer questions, which is great when you launch. A VSL is the evergreen version: one recorded video that does the selling every day. I usually say start with a live webinar to learn the objections, then cut the best version into a VSL. The VSL framework I use is simple: a polarizing hook, the old method, the new method, the proven system, and the unique opportunity. That structure works in both formats.', array['Copy: awareness stages and structures']::text[], 10),
  ('57a7e001-0000-4000-8000-f9265d26dd14', 'Building funnels', 'How do you build a funnel from scratch?', 'build funnel from scratch step by step beginner', 'Follow the Funnel Formula in order. Start with the Client Context: who it is for, their story, the niche, the USP and the traffic temperature. Then the Brand Bullets: positioning, tone, visuals, fonts and palette. Then the Offer Outline. Then decide the strategy, which tells you the funnel type. Only then write the copy, section by section. Design comes after the copy, then the automations like follow up emails and pipelines, then traffic, then CRO. Today AI does most of the heavy lifting in each layer, but it only works if you feed it the right inputs. Garbage context in, generic funnel out.', array['The Funnel Formula']::text[], 11),
  ('57a7e001-0000-4000-8000-0c9772f1ca81', 'Building funnels', 'What sections should every sales page have?', 'sales page sections 17p structure outline', 'I use the 17P''s of Funnel Sections. Promise, Problem, Pain Points, Proof of Results, Personal Epiphany, Process to Solution, Positioning of the offer, Price Anchor, Pricing Tables, Product breakdown of what is inside, Product Bonuses, Proof of Recommendations like testimonials, Perfect Persona of who it is for and not for, Project Spotlight case studies, Pushback Reflex which is your risk reversal, Priority for why to act now, and the Promotional Bar at the top with a final CTA at the bottom. You do not always need all 17, but every section you cut should be a decision, not something you forgot.', array['The 17Ps of funnel sections']::text[], 12),
  ('57a7e001-0000-4000-8000-4db67d214b59', 'Building funnels', 'What is the 10P sales page outline?', '10p outline sales page short version', 'The 10P outline is the compact version of my sales page structure, for when you want every conversion section without a wall of text. It runs Promise, Problem, Pain, Proof, Process, Positioning, Price, Product, Pushback and Priority. Promise the outcome, name the problem and how it feels, prove you can deliver, show the process, position it against the alternatives, anchor the price, show what is inside, reverse the risk and give a reason to act now. When I compress a long page, I keep these ten and make each one scannable instead of cutting sections.', array['The 17Ps of funnel sections']::text[], 13),
  ('57a7e001-0000-4000-8000-87ccee52ce6a', 'Building funnels', 'Which tool do you use to build funnels?', 'tool software platform highlevel build funnels clickfunnels', 'I build everything on HighLevel. Funnels, websites, checkouts, email, pipelines, courses and communities in one place. The reason is simple: when the funnel, the CRM and the follow up live in the same system, nothing falls through the cracks and you are not paying for six tools that do not talk to each other. And with AI Studio inside HighLevel, a lot of the build itself is now done with AI. It is the operating system my whole business runs on. If you earn a commission when people sign up through you, say so when you recommend it.', array['The Funnel Formula']::text[], 14),
  ('57a7e001-0000-4000-8000-88e604cbf1b1', 'Building funnels', 'How long should a sales page be?', 'sales page length long short copy', 'As long as it needs to be to answer every question and objection, and not one line longer. Higher price and colder traffic need more copy, because people need more belief before they buy. A warm audience buying a low ticket product needs much less. The real problem is rarely length, it is long copy that is hard to read. Keep every section, but compress it: short headlines, bullets, visuals, proof blocks and clear CTAs between sections so the reader can buy the moment they are convinced.', array['The 17Ps of funnel sections']::text[], 15),
  ('57a7e001-0000-4000-8000-8f4599fadade', 'Building funnels', 'What should go on a thank you page?', 'thank you page confirmation next step after purchase', 'Most thank you pages waste the moment someone is most likely to say yes again. First, tell them exactly what happens next: check your email, here is your login, here is how to get started. That removes doubt and refunds. Second, give them one next step: join the community, book an onboarding call, watch a quick start video or see an upsell. Third, use it to start the relationship, with a short welcome video from you. A good thank you page makes people feel smart for buying and keeps the momentum going.', array['The Funnel Formula', 'Copy: awareness stages and structures']::text[], 16),
  ('57a7e001-0000-4000-8000-2ab839b4f091', 'Building funnels', 'How do I build a lead magnet funnel?', 'lead magnet optin page free download funnel', 'Keep it to two steps: an optin page and a thank you page. The optin page needs one clear promise in the headline, a short line on what they get, an image of the thing, and a CTA that sells the click, like Download Your Free Guide. Then deliver it instantly and use the thank you page to offer a next step, often a low ticket offer or a call. The magnet itself has to solve one specific problem quickly. A template, a checklist, a calculator or a small tool beats a long ebook nobody reads.', array['Conversion levers for any page', 'The Funnel Formula']::text[], 17),
  ('57a7e001-0000-4000-8000-3b501e812617', 'Building funnels', 'What automations does every funnel need?', 'automations follow up email workflow pipeline', 'At minimum: an instant delivery email, a follow up sequence for people who opt in but do not buy, an abandoned checkout reminder, a welcome and onboarding sequence for buyers, and a pipeline so you can see where every lead is. For high ticket, add booking reminders and a no show follow up. Automations are layer seven of the Funnel Formula for a reason. The page gets the first yes, but the follow up is where most of the sales actually happen. In HighLevel these all live in workflows next to the funnel.', array['The Funnel Formula']::text[], 18),
  ('57a7e001-0000-4000-8000-e589cb54e9ec', 'Building funnels', 'What is a funnel template and should I use one?', 'funnel templates use template copy', 'A template is a starting layout, not a strategy. I love templates because they save hours, but only after the inputs are done. If you have your client context, brand bullets, offer outline and strategy, a template becomes a fast way to build. If you skip those, you end up with a pretty page that says nothing specific, and it will not convert. Use the template for structure and design, then write the copy for your offer first and let it decide which sections stay.', array['The Funnel Formula']::text[], 19),
  ('57a7e001-0000-4000-8000-c5a299c20fec', 'Building funnels', 'How do I build an upsell sequence?', 'upsell one time offer oto downsell order bump sequence', 'Think about what the customer needs right after they buy. The order bump is a small add on at checkout that makes the main purchase better or faster. The first upsell is usually more of the same or a done for you version. A downsell catches people who say no with a lighter or cheaper version. Each step should feel like help, not a trap. The order is: front end offer, order bump, upsell, downsell, thank you page. Make each offer logical, so the customer thinks of course I want that.', array['Ascension and the Profit Maximizer', 'The Funnel Formula']::text[], 20),
  ('57a7e001-0000-4000-8000-83174de577fa', 'Conversion design', 'What is conversion design?', 'conversion design definition what is', 'Conversion design is designing for a decision, not for decoration. Every element on the page has one job: move the right person one step closer to yes. That means a clear hierarchy, a headline that earns the next scroll, proof placed right where doubt shows up, buttons that sell the click, and nothing that distracts from the action. Pretty sites win awards. Conversion design wins customers. The best part is that it is a skill you can learn, because the principles repeat across every niche.', array['Conversion levers for any page']::text[], 21),
  ('57a7e001-0000-4000-8000-f7d75c0e8a4d', 'Conversion design', 'How do you make funnels convert?', 'make funnel convert improve conversion rate', 'First check the offer and the traffic, because a perfect page cannot save the wrong offer sent to the wrong people. Then go through the 11 Step Conversion Checklist. Start with a benefit driven outcome headline. Make the CTA buttons sell the click. Use specific numbers and data to build trust. Show real proof close to the claims. Reverse the risk. Give a real reason to act now. Then test one change at a time and let the data decide. Most funnels do not need a redesign, they need five or six of these fixes.', array['Conversion levers for any page']::text[], 22),
  ('57a7e001-0000-4000-8000-48b419e721a7', 'Conversion design', 'What is the 11 Step Conversion Checklist?', '11 step conversion checklist levers', 'It is a list of conversion levers you can pull without spending more on ads or content. It starts with a benefit driven outcome headline: specific and curiosity based, like Feel Unstoppable Confidence in 7 Days or Less instead of Fix Your Mindset. Then call to action buttons that sell the click instead of saying Submit or Learn More. Then numbers and data, because specific numbers build belief. The rest covers proof, risk reversal, urgency and clarity. Go through it line by line on your page and fix what is missing before you touch the design.', array['Conversion levers for any page']::text[], 23),
  ('57a7e001-0000-4000-8000-82d54b977e6b', 'Conversion design', 'How do I write a headline that converts?', 'headline converts write headline headlines best headline benefit outcome', 'Your headline has one job: make them want to read the next line. People ask themselves if this is worth their time or if they should click off. So make it benefit driven, which is why they should care, and outcome focused, which is the result they get. Make it specific and curious. Instead of Fix your mindset, fix your life, say Feel Unstoppable Confidence in 7 Days or Less. Do the same with the subheadline: a simple mechanism, a timeframe, and a guarantee if you have one.', array['Conversion levers for any page']::text[], 24),
  ('57a7e001-0000-4000-8000-c8bae22e256c', 'Conversion design', 'What should my CTA buttons say?', 'cta button text call to action copy', 'Never Submit, Click Here or Get Started. Those are not specific and nobody wants to get started. Sell the click. What are they getting and how? Turn the action into a benefit: Get Instant Access Now, Download Your Free E-book, Book Your Free Discovery Call. Words like free and instant make it stronger. It is fine to keep the action, like book your call or apply, but make it benefit driven. A game plan session says it is about their strategy. An application says it is exclusive. Switch from please buy energy to here you go, you are welcome energy.', array['Conversion levers for any page']::text[], 25),
  ('57a7e001-0000-4000-8000-298fde29d29e', 'Conversion design', 'How do I use proof on a sales page?', 'social proof testimonials case studies trust', 'Put proof right where the doubt appears. After the promise, show that people like them got the result. After the price, show that it was worth it. Use three kinds: proof of results like screenshots and case studies, proof of recommendations like testimonials and logos, and project spotlights that tell the full before and after story. Specific beats general. A testimonial with a name, a face and a real result does more than ten that say great course. If you are new, visual proof of what you built counts too.', array['The Evidence Quadrant', 'The 17Ps of funnel sections']::text[], 26),
  ('57a7e001-0000-4000-8000-e8757e8c9315', 'Conversion design', 'How do I run an A/B split test on my funnel?', 'ab test split test funnel optimize', 'Test one thing at a time, and test the big levers first: the headline, the offer, the price, the hero section and the CTA. Button colors come last. Split the traffic evenly, decide what success means before you start, and let it run until you have enough conversions to trust the result, not just a few days of clicks. Keep a simple log of every test and what you learned, so the next page starts from your winners. CRO is the last layer of the Funnel Formula because you need traffic and a working funnel before testing means anything.', array['Conversion audit order', 'The Funnel Formula']::text[], 27),
  ('57a7e001-0000-4000-8000-33e19de7a74f', 'Conversion design', 'Why is my landing page not converting?', 'landing page not converting low conversion fix diagnose traffic but no sales', 'Find the cause before you redesign. Is the traffic matched to the step? Cold traffic on a high ticket sales page will not convert. Is the offer actually New, Better, Faster or Convenient? Does the headline make a specific promise? Is there proof close to the claims? Do the buttons sell the click? Is there a reason to act now, and is the risk reversed? Check the page on a phone, because most people will see it there. Usually it is two or three of these, not the design. Fix the biggest leak first.', array['Conversion audit order', 'Conversion levers for any page']::text[], 28),
  ('57a7e001-0000-4000-8000-719892239d1d', 'Conversion design', 'How do I use urgency without being pushy?', 'urgency scarcity deadline priority honest', 'Urgency only works when it is real. A launch that actually closes, a bonus that really expires, a price that goes up on a date, or limited spots because you can only take so many clients. Fake countdown timers that reset kill trust. I call this section Priority: give them an honest reason why acting now is better for them, not just for you. Often the best urgency is the cost of waiting: every month without the result costs them something. Show them that cost and the decision gets easier.', array['The Evidence Quadrant', 'The 17Ps of funnel sections']::text[], 29),
  ('57a7e001-0000-4000-8000-5ca79f41f781', 'Conversion design', 'What is a risk reversal and how do I write one?', 'risk reversal guarantee pushback reflex money back', 'Risk reversal, the Pushback Reflex in my 17P''s, removes the fear of making the wrong decision. The classic is a money back guarantee, but you can also use a free trial, a free sample, or a promise to keep working until they get the result. Write it in plain language and put it near the price and the final CTA, because that is where hesitation peaks. The stronger your offer, the bolder the guarantee you can afford. If you are not willing to guarantee anything, ask yourself if the offer is ready.', array['The Evidence Quadrant', 'The 17Ps of funnel sections']::text[], 30),
  ('57a7e001-0000-4000-8000-47c42905d9d3', 'Copywriting', 'How do I use AI to write high converting copy?', 'ai copywriting high converting chatgpt claude write copy', 'AI is only as good as the context you give it. Before you ask for copy, give it the client context, the brand bullets, the offer outline and the funnel strategy. Then give it a structure, like the 17P''s or the 10P outline, and ask for one section at a time instead of the whole page at once. Add examples of copy you like and copy you hate. Then edit. AI writes a strong first draft fast, but you still need to cut the generic lines, add real proof and make the promise specific. Context in, conversions out.', array['The Funnel Formula', 'Copy: awareness stages and structures']::text[], 31),
  ('57a7e001-0000-4000-8000-c3fee940dd57', 'Copywriting', 'How do you make AI write like me?', 'ai write like me voice tone brand voice writing style', 'Give it your real writing, not a description of it. Collect ten to twenty things you have written that sound like you: posts, emails, transcripts of you talking. Ask the AI to study them and write down your voice rules: sentence length, words you use, words you never use, how you open and close. Save that as a voice guide and add it to every prompt. Then keep correcting it. When it writes something you would never say, tell it why and update the guide. After a few rounds it stops sounding like AI and starts sounding like you.', array['Copy: awareness stages and structures']::text[], 32),
  ('57a7e001-0000-4000-8000-8e10c3be22ce', 'Copywriting', 'What copywriting frameworks do you use?', 'copywriting frameworks pas aida structure', 'For pages, the 17P''s of Funnel Sections and the shorter 10P outline. For ads, my Winning Ad Formula. For video sales letters, the VSL framework: polarizing hook, old method, new method, proven system, unique opportunity. For stories, my 9 Story Selling Frameworks, which are built around the beliefs your buyer needs to have. And for headlines, I use the formula of benefit, outcome, specificity and curiosity. Frameworks are not there to make copy sound the same. They make sure you do not forget the parts that make people buy.', array['Copy: awareness stages and structures']::text[], 33),
  ('57a7e001-0000-4000-8000-158ba8f26958', 'Copywriting', 'What is the Winning Ad Formula?', 'winning ad formula ad copy facebook ads structure', 'It is the structure I use for long form ads. Open with a hook that stops the scroll and calls out the problem, promise or opportunity. Say why they should listen to you. Set a high perceived value, then show the lower price. Show the easy button. Add proof. Tease what they do not know yet. Show how simple it is. Use a metaphor so they can picture it. Break down the steps. Name the system. Show the effort that went into it. Stack the bonuses. Tell them exactly what to do, add real urgency, explain what happens after they buy, and reverse the risk.', array['Copy: awareness stages and structures']::text[], 34),
  ('57a7e001-0000-4000-8000-43048cd006c2', 'Copywriting', 'How do I write a hook that stops the scroll?', 'hook scroll stopper opening line attention', 'A hook has one job: make the right person stop and think, that is me. Call out a specific problem, a bold promise or a surprising opportunity. Be specific instead of clever. Numbers help, because specificity builds belief. A polarizing angle helps too: say what most people get wrong. Test several hooks on the same content, because the hook decides most of the result. And make sure the rest of the post or ad pays off what the hook promised, otherwise you just trained people to ignore you.', array['Copy: awareness stages and structures']::text[], 35),
  ('57a7e001-0000-4000-8000-42484dca7c3c', 'Copywriting', 'How do I use stories to sell?', 'story selling storytelling sell through stories', 'Stories let people reach the conclusion themselves, so you do not have to convince them. Every buyer has beliefs that stop them, usually because something happened before: I tried that and it did not work, I am not techy. A story that shows someone like them overcoming that exact belief changes it. The 9 Story Selling Frameworks are built around those beliefs. When I started telling a story about how brands moved from newspaper ads to online marketing, instead of explaining why social media matters, people started saying yes on their own.', array['Copy: awareness stages and structures']::text[], 36),
  ('57a7e001-0000-4000-8000-f7b21b07f983', 'Copywriting', 'How do I write a VSL script?', 'vsl script video sales letter write', 'Use five parts. A polarizing hook that challenges what they believe. The old method they are using now and why it keeps failing. The new method, your different way of getting the result. The proven system, the steps and the proof that it works. And the unique opportunity, your offer and why now. Keep it conversational, as if you are talking to one person. Write it, read it out loud, cut everything that sounds like a commercial, then record it. You can also feed this structure to AI with your offer outline for a strong first draft.', array['Copy: awareness stages and structures']::text[], 37),
  ('57a7e001-0000-4000-8000-0a2459951e9d', 'Copywriting', 'What makes copy sound like AI and how do I avoid it?', 'ai slop generic copy sounds like ai avoid', 'You can spot it fast: hype words, empty phrases like unlock your potential, three adjectives in a row, perfect parallel lists, dramatic contrast lines and endings that summarize what you just read. To avoid it, give the AI your voice guide and real examples, ask for plain language, and ban the phrases you hate. Then edit with one question: would I actually say this to someone across the table? If not, rewrite it. Specific details, real numbers and real stories are the fastest cure for generic copy.', array['Copy: awareness stages and structures']::text[], 38),
  ('57a7e001-0000-4000-8000-4fd372bce6ea', 'Copywriting', 'How do I write email sequences that sell?', 'email sequence nurture sales emails write', 'Every email should have one idea and one action. A nurture sequence builds the beliefs your buyer needs: tell a story, share a lesson, show proof, handle an objection, and invite them to the next step. A sales sequence around a launch opens the cart, stacks the value, answers objections, shares proof and closes with honest urgency. Write subject lines that make them curious enough to open. Write like you are emailing one friend, not a list. And send consistently, because the people who buy are often the ones who read for weeks first.', array['Email that sells', 'Copy: awareness stages and structures']::text[], 39),
  ('57a7e001-0000-4000-8000-68d1f46680b0', 'Copywriting', 'How do I handle objections in my copy?', 'objections handle copy faq overcome', 'Most objections fall into three groups: the product, the people and the priority. Product: will this work for me? People: can I trust you? Priority: why now? List every objection you have heard, then answer each one somewhere on the page, through a story, proof, the guarantee, the who this is for section or the FAQ. Do not wait until the FAQ to answer the big ones. If price is the main objection, anchor the value before you show the price. Copy that answers objections before they are raised feels like it is reading their mind.', array['Copy: awareness stages and structures']::text[], 40),
  ('57a7e001-0000-4000-8000-f9cfc1dfb87d', 'Offers and pricing', 'How do I create an irresistible offer?', 'irresistible offer create offer design', 'Start with the transformation: where they are now and where they want to be. Then make the vehicle better than their alternatives. I score every offer on the Golden Offer Quadrant: is it New, Better, Faster or Convenient? Then stack it: the core product, bonuses that kill specific objections, a strong guarantee and a price anchor so it feels like a no brainer. An irresistible offer is not about adding more stuff. It is about removing every reason to say no while making the result feel closer and easier.', array['The 3T Offer Triangle', 'The Funnel Formula']::text[], 41),
  ('57a7e001-0000-4000-8000-7e3168f60a4f', 'Offers and pricing', 'What is the Golden Offer Quadrant?', 'golden offer quadrant new better faster convenient', 'It is how I score an offer before I build anything. New: is it a new way of getting the result, not just the same thing with a new name? Better: does it get a better result than the alternatives? Faster: does it get the result in less time? Convenient: is it easier, with less effort, fewer steps or done for them? An offer that wins on at least one of these has a reason to exist. One that wins on several is easy to sell. If it wins on none, fix the offer before you write the funnel.', array['The 3T Offer Triangle', 'The Funnel Formula']::text[], 42),
  ('57a7e001-0000-4000-8000-a3155cd96844', 'Offers and pricing', 'How should I price my offer?', 'price pricing how much charge price point', 'Price follows the transformation and your positioning, not your hours. Ask what the result is worth to them and what their alternatives cost. Then pick a price point strategy that fits your funnel: low ticket to acquire customers, mid ticket for programs and products, high ticket for coaching and done for you. Anchor the value before you reveal the price, so the gap feels obvious. Beginners charge for time. Specialists charge for experience and outcomes. And once you are out of the beginner phase, do not price from desperation.', array['The 3T Offer Triangle', 'Content, personal brand and YouTube']::text[], 43),
  ('57a7e001-0000-4000-8000-251539891bd8', 'Offers and pricing', 'What is a price anchor?', 'price anchor anchoring value stack', 'A price anchor sets a reference point so your real price feels like a deal. You show the value first: what it would cost to hire someone, buy the pieces separately or keep living with the problem. Then you show your price. The contrast does the selling. In my 17P''s, the Price Anchor comes right before the pricing tables for that reason. The anchor has to be honest, based on real alternatives. An inflated fake value backfires because smart buyers can feel it.', array['The 3T Offer Triangle', 'The 17Ps of funnel sections']::text[], 44),
  ('57a7e001-0000-4000-8000-a187b7930ce8', 'Offers and pricing', 'How do I create a value ladder or ascension path?', 'value ladder ascension path offer ladder', 'Map the steps your customer takes from first hearing about you to your highest level of help. Free content and lead magnets at the bottom, then a low ticket product, then a core program, then high touch coaching or done for you. Each step should solve the next problem the customer has after the last step worked. That is what makes ascension feel natural instead of salesy. Build the funnel for each step and the automations that invite people up when they are ready.', array['Ascension and the Profit Maximizer', 'The 3T Offer Triangle']::text[], 45),
  ('57a7e001-0000-4000-8000-e1d419161cbf', 'Offers and pricing', 'What bonuses should I add to my offer?', 'bonuses offer stack add bonuses', 'Every bonus should kill a specific objection or speed up the result. If they think it will take too long, add a template or a done for you piece. If they think they are not techy, add a setup walkthrough. If they worry about getting stuck, add support or a community. Bonuses that are just more content make the offer heavier, not better. Name them clearly, show what each one does for them, and stack them so the perceived value climbs as they read.', array['The 3T Offer Triangle', 'The 17Ps of funnel sections']::text[], 46),
  ('57a7e001-0000-4000-8000-cc161a61e840', 'Offers and pricing', 'What is a productized service?', 'productized service package service fixed scope', 'A productized service is a service sold like a product: a clear scope, a fixed price, a defined timeline and the same delivery process every time. Instead of custom quotes and endless calls, you sell one package that solves one problem. For funnel builders that might be strategy, branding, copy, build, optimization and email as one full stack offer. It is easier to sell because the buyer knows exactly what they get, and easier to deliver because you can systemize and use AI for most of it.', array['The 3T Offer Triangle']::text[], 47),
  ('57a7e001-0000-4000-8000-f3b2ca279a8c', 'Offers and pricing', 'Should I offer a free sample or free work?', 'free sample free work spec work free trial', 'A small, personalized gift before you ask for anything is one of the best ways to start a client relationship. A redesigned section of their page, an audit, or one sample. No risk and no effort for them, they just say yes. Show what you did, do not say what you will do. But keep it small and strategic. The goal is proof that starts a conversation, not free projects. And if someone already loves your work, skip the sample and go straight to price and start date.', array['DM sales: Connect, Collect, Close', 'The 3T Offer Triangle']::text[], 48),
  ('57a7e001-0000-4000-8000-af41a9732bca', 'Offers and pricing', 'What are the beliefs someone needs before they buy?', 'beliefs buyer needs before buying 12 beliefs', 'I map 12 beliefs. They want the outcome and value it. They admit they have a problem and want it solved soon. They believe your solution will solve it. They trust you are the right person. It makes sense why they have not solved it yet. They see why your process is better. Others got results, which gives them hope. It is worth more than the price. They are willing to make time for it. The risk of doing nothing is bigger than the risk of trying. They know the next steps. And they feel urgency to solve it now. Your page, VSL or call should build every one of them.', array['The 12 buyer beliefs', 'Copy: awareness stages and structures']::text[], 49),
  ('57a7e001-0000-4000-8000-946ee67c5da4', 'Offers and pricing', 'What is the Profit Maximizer?', 'profit maximizer ascension backend profit', 'The Profit Maximizer is my ascension model. Free: freebie funnels that get leads, build trust and make people want more. Low ticket: a mass market offer that turns strangers into customers and automates the flow. Mid ticket: automated offers with more help and direct access. Back end: a high ticket offer sold through an application funnel. The front end gets the customer, and the back end grows the business. When every customer has a logical next step, each one becomes worth more, which means you can afford to reach more of them.', array['Ascension and the Profit Maximizer', 'The 3T Offer Triangle']::text[], 50),
  ('57a7e001-0000-4000-8000-4234fac4497e', 'Getting clients', 'How do you get clients from scratch as a beginner?', 'get clients beginner first client from scratch no experience', 'Start with three steps: Position, Promotion and Partner. Position first: pick one growing market with purchase power, one clear offer and a small portfolio. If you have no clients, build concept projects that show what you can do. Then Promotion: a magnet like a free audit, gift first outreach and content that brings people to you. Then Partner: close by auditing, consulting and prescribing, not pitching. The beginner mistake is waiting until you feel ready. Build proof first, then go give value to people who need it.', array['Getting your first clients']::text[], 51),
  ('57a7e001-0000-4000-8000-75b76fb8574d', 'Getting clients', 'What is the framework for selling funnels?', 'framework selling funnels sell funnel services funnel builder', 'I teach it as Position, Promotion and Partner. Position: choose a market, package a full stack funnel offer with strategy, branding, build, optimization and email, and build a portfolio that sells for you. Promotion: create magnets like audits, templates or small tools, do gift first outreach, and post content that compounds. Partner: close by auditing their business, acting like a consultant and prescribing what they need, then retain them by running their business on HighLevel and ascend them into bigger work. You are not selling a funnel. You are selling the outcome.', array['Getting your first clients']::text[], 52),
  ('57a7e001-0000-4000-8000-c154e418674e', 'Getting clients', 'How do I build a portfolio with no clients?', 'portfolio no clients concept work spec projects', 'Build concept funnels. Pick real brands or creators in your market and design what their funnel could look like, then show it. Add your own sites and funnels running live. A good portfolio site has a hero promise in one line, concept funnels, client funnels when you have them, your own projects, an about section with your process, and a clear CTA with an FAQ. Results when you start out can be visual, not only data. A great concept piece is often what lands the first client.', array['Getting your first clients', 'Content, personal brand and YouTube']::text[], 53),
  ('57a7e001-0000-4000-8000-50b61e6e787b', 'Getting clients', 'How do I do cold outreach that actually works?', 'cold outreach dm outreach message prospects', 'Send a personalized gift before you ask for anything. Gift first, made for them, no risk and no effort on their side. Show what you did, do not say what you will do. For a funnel builder that might be a redesigned hero section of their page or a short audit video. Keep the message short and straight to the point. Skip the long intro and the request for a call. Ask for a yes to something easy. Designers and editors do this in my inbox every week, and the good ones get hired.', array['Getting your first clients', 'DM sales: Connect, Collect, Close']::text[], 54),
  ('57a7e001-0000-4000-8000-344fa64b76d3', 'Getting clients', 'What lead magnet should I use to get clients?', 'lead magnet get clients audit template tool', 'Something your ideal client cannot ignore and can use today. A free audit of their funnel or site. A template. A small tool or calculator that solves one problem. Then promote it with a two step post: post the offer and deliver it when they comment or message you. You can also find leads in other people''s communities and in your own newsfeed. The magnet should naturally lead to your paid service. If you sell funnels, a funnel audit is perfect because it shows them exactly what they are missing.', array['Getting your first clients']::text[], 55),
  ('57a7e001-0000-4000-8000-39f85135c7e6', 'Getting clients', 'Which niche should I pick?', 'niche pick choose market which niche', 'Pick a growing market with purchase power. Look for clients who can pay every month, personal brands that want to be the face and outsource the tech, and businesses with multiple offers, because more offers means more funnels to build. And pick an industry you care about, because you will be in it for years. I chose education and the info space: coaches, creators and experts. The money is in the market you understand well enough to speak their language.', array['Getting your first clients']::text[], 56),
  ('57a7e001-0000-4000-8000-044bd0a1ca44', 'Getting clients', 'How do I get clients through content?', 'inbound content clients posting attract', 'Content that brings clients to you compounds over time. Post what you are building right now, client words and results, behind the scenes of how your builds come together, life updates about the person behind the business, and lessons you learned this week. Referrals come from happy clients who see you everywhere. The trick is consistency. One post will not do much, but a habit of showing your work turns your feed into a portfolio that sells while you sleep.', array['Getting your first clients']::text[], 57),
  ('57a7e001-0000-4000-8000-bd9d5ece30a7', 'Getting clients', 'How do I get referrals?', 'referrals word of mouth happy clients refer', 'Referrals are the last step of the flywheel: Ignite. They come from clients who got a great result and feel looked after. So deliver beyond what you promised, make the experience easy, and then ask. The best time is right after a win. Make it simple: who else do you know who needs this? A referral bonus or a thank you gift helps, but the real driver is the result. Then post the client win publicly with their permission, because that brings in the next one.', array['Getting your first clients']::text[], 58),
  ('57a7e001-0000-4000-8000-85a3e031101b', 'Getting clients', 'How do I stand out from other funnel builders?', 'stand out competition different funnel builders', 'Do not compete on price. Compete on positioning. Most people sell funnel design. Position yourself as a growth partner who owns the outcome: strategy, conversion design, build, automations and optimization. Pick one market and speak its language. Show proof in your portfolio. Use a named framework so people see a system, not a freelancer. And be the person who gives value first. When you are the obvious choice in one niche, the competition becomes irrelevant.', array['Content, personal brand and YouTube', 'Getting your first clients']::text[], 59),
  ('57a7e001-0000-4000-8000-d06e5e54d2ee', 'Getting clients', 'How do I find clients in communities?', 'communities facebook groups online communities find clients', 'Go where your clients already hang out: Facebook groups, online communities, LinkedIn and comment sections of people in your niche. Do not pitch. Answer questions, share useful breakdowns and post your free audit or template where it is allowed. When someone engages, follow up in messages with a personalized gift. People hire the person who helped them before they ever asked. Over time, build your own newsfeed so leads come to you instead of you always going to them.', array['Getting your first clients']::text[], 60),
  ('57a7e001-0000-4000-8000-0fade49e19a9', 'Selling and closing', 'How do you close clients in the DMs?', 'dm closing close clients messages without calls', 'I do the opposite of what every closer does. I do not close deals, I help people come to conclusions themselves. Think about how you hire. When I hire a thumbnail designer, I want three things: examples of their work, their price and how many they can do per week. Proof, pricing and availability. So give buyers those three things fast and keep messages short. Audit their business first, then prescribe what they need like a doctor. I use the 3 C''s: Connect, Collect, Close. When it feels like help, the close takes care of itself.', array['DM sales: Connect, Collect, Close']::text[], 61),
  ('57a7e001-0000-4000-8000-8861be1a15f1', 'Selling and closing', 'What are the 3 Cs of closing?', '3 cs connect collect close', 'Connect, Collect, Close. Connect: start a real conversation, ideally after giving something of value first, and show you understand their world. Collect: ask questions and audit their situation so you know where they are, where they want to be and what is in the way. Close: prescribe the solution like a doctor, sell the vision first, then agree on scope, price and start date. Never desperate and never attached. If it is not a fit, say so. That honesty is a big part of why people say yes when it is.', array['DM sales: Connect, Collect, Close']::text[], 62),
  ('57a7e001-0000-4000-8000-f536794bc460', 'Selling and closing', 'Do I need sales calls to sell high ticket?', 'sales calls high ticket without call', 'Not always. A lot of high ticket deals close in messages when the buyer gets what they need fast: proof of results, the price and how soon you can deliver. Successful people make decisions fast and informed, and many prefer not to spend an hour on a call. That said, a call is great when the deal is complex or the buyer wants it. Offer both. The skill is the same either way: audit, consult, prescribe, and let them come to the conclusion themselves.', array['DM sales: Connect, Collect, Close']::text[], 63),
  ('57a7e001-0000-4000-8000-962e0d1f2798', 'Selling and closing', 'How do I handle the it is too expensive objection?', 'too expensive price objection cant afford', 'Usually it means the value is not clear yet, not that they cannot pay. Go back to the transformation: what is the result worth to them, and what does staying stuck cost every month? Anchor against the alternatives, like hiring a team or doing it themselves and losing months. If the value is clear and it is still too much, offer a smaller scope or a lighter version instead of dropping your price. Discounting teaches clients your price was never real.', array['DM sales: Connect, Collect, Close', 'The 3T Offer Triangle']::text[], 64),
  ('57a7e001-0000-4000-8000-cf6adcd7def4', 'Selling and closing', 'How do I follow up without being pushy?', 'follow up leads not pushy ghosted', 'Follow up with value, not with did you see my message. Send a quick idea for their funnel, a relevant case study or a short video. Keep it light and give them an easy way to say not now. Most deals close on the follow up, so do it, but be the person they are happy to hear from. If they go quiet after a few tries, leave the door open and move on. Being unattached is what makes people come back.', array['DM sales: Connect, Collect, Close']::text[], 65),
  ('57a7e001-0000-4000-8000-ea8def7302ec', 'Selling and closing', 'What is the magic price anchor close?', 'price anchor close one line magic', 'It is a one line anchor you use before saying the price, so the number lands against the value instead of against zero. You reflect back what they told you the result is worth, or what hiring for it would normally cost, then give your price. Done well, the price feels like the obvious next step, not a shock. The anchor must be honest and based on their own words.', array['The 3T Offer Triangle', 'DM sales: Connect, Collect, Close']::text[], 66),
  ('57a7e001-0000-4000-8000-8c0b6e6df7fb', 'Selling and closing', 'How do I retain and ascend clients?', 'retain clients ascend upsell clients retention', 'Retain: run their business on HighLevel so you become part of how they operate, not a one time project. Monthly optimization, email, rebrands, site updates and new offer launches keep you useful. Ascend: when they get results, offer the next level, like more funnels, a SaaS plan or a bigger strategy role. The best clients are the ones you already have. It is far easier to grow with a happy client than to find a new one.', array['DM sales: Connect, Collect, Close']::text[], 67),
  ('57a7e001-0000-4000-8000-0732fef60794', 'Selling and closing', 'How do I sell the vision to a client?', 'sell the vision client demo before after', 'Show them the future before you talk about the work. A concept of their new funnel, a mockup of their dashboard, or a quick demo of what their business looks like with the system running. People buy the outcome they can picture. Once they see it and want it, the conversation shifts from whether to how: scope, price and start date. That is why a visual demo often closes better than any pitch.', array['DM sales: Connect, Collect, Close']::text[], 68),
  ('57a7e001-0000-4000-8000-f056cba9157b', 'Digital products', 'What is the process to create digital products using AI?', 'create digital products ai process build product', 'Start with the transformation your customer wants, then package it with a tool they use every week. The structure is simple: their input, your method, their output. A meal planner, a workout builder, a margin calculator or a couple''s check in. AI helps at every step: researching the market, drafting the method, building the tool, writing the sales page and creating the content. Then put it in a funnel on HighLevel so it sells, delivers and nurtures for you. One person, one transformation, one tool.', array['Digital products']::text[], 69),
  ('57a7e001-0000-4000-8000-d3971dcaa790', 'Digital products', 'What digital product should I create first?', 'first digital product idea what to sell', 'Pick one transformation you can help with, in a market where people already spend money: wealth, health or relationships. Then think about what they would use every week, not something they read once. A tool, a template, a planner or a calculator. Validate it before you build too much: talk to people, presell or run a small test. Your first product should be simple, specific and quick to deliver. You can always build a bigger offer on top once people buy.', array['Digital products']::text[], 70),
  ('57a7e001-0000-4000-8000-cedbb7060173', 'Digital products', 'Why do most courses fail?', 'courses fail nobody finishes course old way', 'Most digital products get bought, then forgotten. The 40 hour course nobody finishes, because most buyers stop after the first few lessons and never get the result. The PDF that sits in downloads, because information alone does not change what they do on Monday. And one to one coaching caps your time. The fix is to sell a transformation packaged with a tool they use every week. When the product becomes part of their routine, they get results, they stay and they buy again.', array['Digital products']::text[], 71),
  ('57a7e001-0000-4000-8000-6227569a0588', 'Digital products', 'How do I turn my knowledge into a product?', 'turn knowledge expertise into product productize', 'Write down the method you already use to get results, step by step. That is your process. Then ask what the customer puts in and what they get out. Input, your method, output. Turn that into a tool, a template or a short program that walks them through it. AI can help you pull the method out of your head: record yourself explaining it and ask AI to structure it. Then name the framework, because a named system feels more valuable and easier to trust.', array['Digital products']::text[], 72),
  ('57a7e001-0000-4000-8000-9ea150b0cafe', 'Digital products', 'How do I price a digital product?', 'price digital product subscription monthly lifetime', 'Price the transformation and the format. Monthly works well when the tool is used every week and keeps delivering value. Lifetime or one time works for a template, a bundle or a course. A low ticket entry product is great for getting customers in, then ascend them to higher value products. Look at what your market already pays for similar results, anchor the value against alternatives, and test. The right price is the one your funnel can profitably sell.', array['Digital products', 'The 3T Offer Triangle']::text[], 73),
  ('57a7e001-0000-4000-8000-fed8764f22f0', 'Digital products', 'How do I sell digital products without a big audience?', 'sell digital products small audience no audience', 'You need a funnel and a small number of the right people, not a big audience. Start with a low ticket offer and run small ads or targeted content to it. Use the front end to acquire customers, and let the upsells and ascension make the money. Build an email list from day one. Every buyer is worth more than ten followers. And post content that shows the product working, because a demo sells better than a promise.', array['Digital products']::text[], 74),
  ('57a7e001-0000-4000-8000-a662290a94ca', 'Digital products', 'Should I sell a course, a membership or a tool?', 'course vs membership vs tool software', 'Ask how the customer gets the result. If they need to learn a skill once, a short course works. If they need ongoing support and accountability, a membership or community works. If they need to do something repeatedly, a tool wins, because it becomes part of their week. My favorite is a transformation packaged with a tool, with a little teaching around it. Tools have the best retention because people keep using them.', array['Digital products']::text[], 75),
  ('57a7e001-0000-4000-8000-af213d11e1eb', 'Digital products', 'How do I deliver digital products on HighLevel?', 'deliver digital products highlevel course membership', 'HighLevel handles the whole thing. The funnel sells it, the checkout takes payment, memberships and courses deliver it, communities keep people engaged, and workflows handle onboarding, nurture and ascension. You can even build small tools and apps with AI Studio. Having it all in one place means the customer never falls through the cracks, and you can see who bought, who is using it and who is ready for the next offer.', array['Digital products']::text[], 76),
  ('57a7e001-0000-4000-8000-cf8dc4a22689', 'Digital products', 'What is a micro tool and why build one?', 'micro tool small app calculator lead magnet build', 'A micro tool is a small app that solves one problem: a calculator, a generator, a planner or an audit. It works as a lead magnet, a product or a bonus. People love tools because they get a result in seconds, which is much more valuable than another PDF. With AI builders you can make one in an afternoon. Give it away to collect leads, or sell it as a monthly subscription if people use it every week.', array['Digital products']::text[], 77),
  ('57a7e001-0000-4000-8000-a31ed5f04f13', 'Personal brand', 'What''s the secret to building a personal brand?', 'personal brand secret build brand', 'There is no single secret, there are 12 principles. Personality: are you likable? Authority: are you speaking from expertise? Positioning: are you a commodity or a crucial part of their growth? Credibility: what results do you have? Pricing: would someone with 10 years of experience charge your fees? Relevance: do you speak their language? Engagement: are you validated by a community? Then Framework, Portfolio, Association, Endorsement and Celebrity. Work on them one at a time. Consistency over years is what compounds.', array['Content, personal brand and YouTube']::text[], 78),
  ('57a7e001-0000-4000-8000-6e9f34709ae5', 'Personal brand', 'What are the 12 principles of personal branding?', '12 principles personal branding list', 'Personality, Authority, Positioning, Credibility, Pricing, Relevance, Engagement, Framework, Portfolio, Association, Endorsement and Celebrity. The first ones are about how people perceive you: likable, expert, positioned as essential and credible. The middle ones are about how you show up: pricing like a specialist, speaking their language and building real engagement. The last ones are leverage: a named framework, a portfolio of proof, who you are associated with, who endorses you, and eventually being known in your space.', array['Content, personal brand and YouTube']::text[], 79),
  ('57a7e001-0000-4000-8000-7681ccbc324a', 'Personal brand', 'How do I become an authority in my niche?', 'authority expert niche become known', 'Speak from real experience, not generic information. Language matters and confidence can be felt. Share what you are doing, what you learned and what you would do differently. Name your frameworks so people see a system. Show results for yourself and others. Associate with respected people and brands in your space, and get endorsements when you can. Authority is built in public over time, so pick one topic and become the person people think of first.', array['Content, personal brand and YouTube']::text[], 80),
  ('57a7e001-0000-4000-8000-45337e561f65', 'Personal brand', 'What should I post on social media?', 'what to post content ideas social media instagram linkedin', 'Post what you are building right now, client results and testimonials, behind the scenes of how your work comes together, lessons you learned this week, and updates about the person behind the business. Mix teaching with proof and personality. Teach to build authority, show proof to build credibility and share your story to build connection. Ideas come from your own work, so keep notes of everything you build and every question people ask you.', array['Content, personal brand and YouTube']::text[], 81),
  ('57a7e001-0000-4000-8000-10b1846275f0', 'Personal brand', 'What is the CONTENT framework?', 'content framework c o n t e n t', 'C.O.N.T.E.N.T is seven types of content that grow a business, not just an audience. Customer Results: proof through success stories and projects. Offer Differentiation: the USP that makes you different. New Discoveries: lessons you are learning right now. Thought Leadership: truths you believe in, even when they are unpopular. Education and Entertainment: helpful tips that do not sound robotic. Narrative Framing: stories, metaphors and analogies. Trends and News: be the source for what is happening in your industry. Mix all seven and your feed builds proof, authority and connection at the same time.', array['Content, personal brand and YouTube']::text[], 82),
  ('57a7e001-0000-4000-8000-5106429a4a00', 'Personal brand', 'How do I write posts that get engagement?', 'posts engagement facebook posts hype write', 'Start with a hook that calls out one person. Tell a short story or share one specific lesson. Use plain language and short lines. End with a simple question or a two step call to action, like comment a word to get the template. Share real results and real behind the scenes, because people engage with what feels human. And reply to every comment early, because engagement on your own post signals that people should pay attention.', array['Content, personal brand and YouTube']::text[], 83),
  ('57a7e001-0000-4000-8000-5aa97f919957', 'Personal brand', 'How do I announce a new offer?', 'announce new offer launch post announcement', 'Lead with what changes for them, not what you made. Tell the story of why you built it, what problem it solves and who it is for. Show a peek inside, add proof from early users if you have it, and give a clear next step with a real reason to act now, like founding member pricing or limited spots. Build anticipation before the launch with behind the scenes posts so the announcement lands on people already curious.', array['Content, personal brand and YouTube']::text[], 84),
  ('57a7e001-0000-4000-8000-c287faebe3e8', 'Personal brand', 'Blue ocean or red ocean, which should I choose?', 'blue ocean red ocean competition market', 'For content, always blue ocean. Red ocean content is the same topics with the same angles everyone else uses, so you become a commodity. Blue ocean content is your unique perspective, new angles and original ideas that cannot be copied, so you own your lane. You can still talk about popular topics, just bring your own framework, your own story or a take others will not say. Then use the Pyramid of Content: engaging content for discovery, entertaining for likability, educational for trust and empowering content for belief and decisions.', array['Content, personal brand and YouTube', 'The Funnel Formula']::text[], 85),
  ('57a7e001-0000-4000-8000-6fba908919d2', 'YouTube', 'How do I grow a YouTube channel?', 'grow youtube channel subscribers views', 'Make videos people want to click and then want to keep watching. That means the idea, the title and the thumbnail come first, before you film. Study what already works in your niche and make a better version. Hook them in the first seconds by confirming the promise of the title. Deliver real value, then point to the next video or your lead magnet. Post consistently and treat each video as an asset that brings in leads for years. YouTube is the best compounding content platform there is.', array['Content, personal brand and YouTube']::text[], 86),
  ('57a7e001-0000-4000-8000-d8d061cf1d44', 'YouTube', 'How do you make YouTube thumbnails?', 'thumbnails youtube design ai thumbnail face', 'I use AI to clone my face for thumbnails. Upload ten or more selfies in different lighting and angles, ask for a mega prompt that describes your face, then ask for a thumbnail with a blank background using that prompt. Add a line asking for the face and hair to look photographically natural, with no synthetic texture and less overprocessing. Then add the text yourself. It saves weekly photoshoots and makes it easy to A/B test several thumbnails per video.', array['Content, personal brand and YouTube']::text[], 87),
  ('57a7e001-0000-4000-8000-e76436ed81e4', 'YouTube', 'How do I come up with YouTube video ideas?', 'youtube video ideas topics what to make', 'Start with the questions your audience already asks you, and the videos that already work in your niche. Look at outliers: videos that got far more views than the channel''s average. Those are proven ideas. Make your version better, more specific or more up to date. Keep a running list from comments, client calls and your own work. Then pick the ideas that lead naturally to your offers, so your channel grows your business and not just your views.', array['Content, personal brand and YouTube']::text[], 88),
  ('57a7e001-0000-4000-8000-61fb32e5faff', 'YouTube', 'How do I write a YouTube title that gets clicks?', 'youtube title clicks ctr write titles', 'Same rules as a headline: benefit driven, specific and curious. Make a clear promise, add a number or a timeframe if it fits, and leave a gap they want to close. The title and thumbnail should work together, not repeat each other. Write ten options, then pick the one you would click. And test, because YouTube now lets you split test titles and thumbnails.', array['Conversion levers for any page', 'Content, personal brand and YouTube']::text[], 89),
  ('57a7e001-0000-4000-8000-d4a6e15e84d6', 'YouTube', 'How do I turn YouTube viewers into customers?', 'youtube viewers customers leads monetize channel', 'Every video needs a next step. Offer a free resource that fits the video, like a template, a checklist or a tool, and put it in the description and pinned comment. That lead magnet goes into a funnel with a follow up sequence and a low ticket or core offer. Mention it naturally in the video where it helps the viewer. Track which videos bring leads, not just views. A video with fewer views that brings buyers is worth more than a viral one that brings nobody.', array['Content, personal brand and YouTube']::text[], 90),
  ('57a7e001-0000-4000-8000-da9cb9668274', 'YouTube', 'How often should I post on YouTube?', 'how often post youtube upload frequency consistency videos per week', 'As often as you can while keeping the quality high. Once a week is a great start for most people. Consistency matters more than volume, because you learn from every upload and the channel builds momentum. If you can only do one great video every two weeks, do that rather than four rushed ones. Use AI to speed up research, scripting, thumbnails and editing so you can post more without lowering the bar.', array['Content, personal brand and YouTube']::text[], 91),
  ('57a7e001-0000-4000-8000-13e324d9fe88', 'YouTube', 'Should I show my face on YouTube?', 'face camera faceless youtube show face', 'If you want to build a personal brand, yes. People buy from people, and your face builds trust and connection faster than anything. Personality is the first of my 12 branding principles for a reason. Faceless channels can work for views, but it is much harder to sell high value offers without a person behind them. If you are nervous on camera, start with screen shares and talk over them, then add your face as you get comfortable.', array['Content, personal brand and YouTube']::text[], 92),
  ('57a7e001-0000-4000-8000-d21dbe0f85f9', 'AI in business', 'How do you use AI in your business?', 'use ai in business how ai workflow', 'I use AI to turn every hour I work into an asset that markets, sells or delivers. Research, strategy, copy, design, building funnels, writing emails, creating content and even building small apps. The rule is that AI is only as good as the context you give it, so I keep my offers, brand, frameworks and voice written down and feed them in every time. The goal is not to do more busy work faster. It is to build assets that keep working when you are not.', array['AI agents and vibe coding']::text[], 93),
  ('57a7e001-0000-4000-8000-bf70f630e410', 'AI in business', 'How do you design funnels using AI?', 'design funnels ai ai design funnel', 'Do the thinking first, then let AI build. Give it the client context, brand bullets, offer outline and the funnel strategy. Then the copy, because copy decides the layout. Then give it design direction: reference sites you like, your fonts and palette, and the mood. Ask for one section at a time and review each one against the 11 Step Conversion Checklist. AI Studio inside HighLevel can now build most of the page for you. Your job is taste and conversion judgment.', array['The Funnel Formula', 'Conversion levers for any page']::text[], 94),
  ('57a7e001-0000-4000-8000-72bdb4e85822', 'AI in business', 'What is the 1 Person Business Model?', '1 person business model solopreneur one person business', 'It is a simple solopreneur business you can run from anywhere, without a team or an expensive office. Low overhead and low capital to start, high margins and a lot of calendar freedom. The how is funnels built on HighLevel using AI. Every hour you work turns into a digital asset that markets, sells or delivers. You sell products instead of hours. And you build a brand that keeps growing when you are not posting.', array['AI agents and vibe coding']::text[], 95),
  ('57a7e001-0000-4000-8000-136b02a60311', 'AI in business', 'What are the 3 Fastlanes?', 'fastlanes founder digital products affiliate one person business', 'Three ways to build a one person business, with one thing in common: funnels in HighLevel. The Founder Fastlane: sell HighLevel as SaaS plus a service, where funnels are the foot in the door and the full AI operating system becomes what they build on. The Digital Products Fastlane: sell your own products in HighLevel, with funnels that sell, deliver and ascend customers. The Affiliate Fastlane: help new users get started on HighLevel, with funnels and websites as their home online.', array['AI agents and vibe coding']::text[], 96),
  ('57a7e001-0000-4000-8000-051846ddd859', 'AI in business', 'What is HighLevel and why do you use it?', 'highlevel what is gohighlevel ghl why', 'HighLevel is an all in one platform for funnels, websites, CRM, email, SMS, calendars, payments, courses, communities and automations, with a lot of AI built in. I use it because my whole business runs in one place: the funnel, the follow up and the delivery talk to each other. And you can white label it and sell it as your own SaaS. It is the system I build on every day. If you recommend it with an affiliate link, say so.', array['AI agents and vibe coding']::text[], 97),
  ('57a7e001-0000-4000-8000-ac2c0c9f37ab', 'AI in business', 'How do I sell HighLevel as my own SaaS?', 'sell highlevel saas white label agency', 'You do not sell software, you sell the outcome. HighLevel is the engine and your brand is what they buy. Package a productized service, like strategy, branding, build, optimization and email, and add the software as a monthly plan so you have recurring revenue. Funnels get you in the door, and the CRM and automations make them stay. Follow Position, Promotion and Partner. Results vary a lot by effort, skills and market, so build it step by step.', array['AI agents and vibe coding']::text[], 98),
  ('57a7e001-0000-4000-8000-eb9856f5212d', 'AI in business', 'What is AI Studio in HighLevel?', 'ai studio highlevel build with ai', 'AI Studio is where you build inside HighLevel with AI: funnels, websites, small apps and tools, from a prompt and your context. Instead of dragging every block by hand, you describe what you want and refine it. It works best when you bring the inputs: the offer, the copy and the design direction. It is a big part of why one person can now deliver what used to take a team.', array['AI agents and vibe coding']::text[], 99),
  ('57a7e001-0000-4000-8000-4d9fef03bcca', 'AI in business', 'Which AI tools do you recommend?', 'ai tools recommend chatgpt claude stack which tool', 'Use as few tools as you can, and the best model for each job. Strong general models like ChatGPT and Claude for thinking, writing and code. An AI builder for apps and tools. HighLevel for funnels, CRM and delivery, including AI Studio. Then image and voice tools for content. The tool matters less than your context: your offers, brand, frameworks and voice written down so any AI can use them. Tools change every month. A good system keeps working when they do.', array['AI agents and vibe coding']::text[], 100);
